        elif target_dir[0] < 0:
            dx = -1
        if target_dir[1] > 0:
            dy = 1
        elif target_dir[1] < 0:
            dy = -1
        return [dx, dy]

    # Otherwise, try to infer from environment hints
    # If there is an obstacle or enemy info, avoid staying in place if possible
    grid = observation.get("grid", None)
    if isinstance(grid, (list, tuple)):
        h = len(grid)
        w = len(grid[0]) if h > 0 and isinstance(grid[0], (list, tuple)) else 0
        # look around current position for safe move by inspecting adjacent cells
        # We'll prefer moving toward the first safe neighbor in a fixed order: (-1,0),(0,-1),(1,0),(0,1)
        current = observation.get("position", None)
        # If we know current position, we can inspect actual grid relative; otherwise use relative hints
        def is_safe(nx, ny):
            if grid is None:
                return True
            if ny < 0 or nx < 0 or ny >= h or nx >= w:
                return False
            cell = grid[ny][nx] if ny < h and nx < len(grid[ny]) else None
            # treat obstacles marked with 1 or "blocked" as unsafe
            if cell in (1, "blocked", "obstacle"):
                return False
            return True

        # If current is known, compute neighbors in absolute coords if possible
        if isinstance(current, (list, tuple)) and len(current) == 2:
            cx, cy = int(current[0]), int(current[1])
            neighbors = [(-1, 0), (0, -1), (1, 0), (0, 1)]
            for dx, dy in neighbors:
                if is_safe(cx + dx, cy + dy):
                    return [dx, dy]
        else:
            # No current; just pick a safe neighbor around origin
            for dx, dy in [(-1, 0), (0, -1), (1, 0), (0, 1)]:
                if is_safe(0 + dx, 0 + dy):
                    return [dx, dy]

    # Fallback: hold position
    return [0, 0]

